'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={started:false,running:false,time:0,docked:true,size:24,opacity:97,theme:'dark',bilingual:true,originalFirst:false,tab:0,domain:0,focus:'LLVM / Clang',custom:'',cache:null,building:false,progress:0,generatePaused:false,newKnowledge:true};
const CACHE_KEY='livecap.desktop.knowledge.v1';
try{const saved=JSON.parse(localStorage.getItem(CACHE_KEY)||'null');if(saved&&typeof saved.name==='string'&&Array.isArray(saved.terms)&&saved.terms.every(t=>typeof t.term==='string'&&typeof t.translation==='string')){S.cache=saved;S.newKnowledge=false}}catch{}
function saveCache(){try{localStorage.setItem(CACHE_KEY,JSON.stringify(S.cache));return true}catch{notice('缓存未保存，请导出知识库');return false}}
let frame,lastTime=0,lastPaint=0,generation,noticeTimer;
const lines=[['在 Clang 中，Sema 负责检查代码的语义。','In Clang, Sema is responsible for checking the semantics of the code.'],['解析器构建 AST，随后交给 Sema 进行类型检查。','The parser builds the AST, which is then passed to Sema for type checking.'],['如果类型不匹配，编译器会在这一阶段给出诊断信息。','If the types do not match, the compiler produces a diagnostic at this stage.'],['接下来，这些信息会被转换为 LLVM IR，用于后续优化。','Next, this information is lowered to LLVM IR for subsequent optimization.']];
function wave(){return `<span class="wave ${S.running||S.building&&!S.generatePaused?'moving':''}" aria-hidden="true">${'<i></i>'.repeat(7)}</span>`}
function time(){return String(Math.floor(S.time/60)).padStart(2,'0')+':'+String(Math.floor(S.time%60)).padStart(2,'0')}
function notice(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').hidden=true,2200)}
function control(){const body=$('#control-body');body.innerHTML=`<div class="control-content">${S.started?`<div class="active-summary">${wave()}<p>${S.running?'正在聆听系统音频':'字幕已暂停'}</p><div class="elapsed" id="elapsed">${time()}</div></div><div class="control-row"><span>翻译</span><strong>英语 → 简体中文</strong></div><div class="control-row"><span>领域</span><button data-action="knowledge">${S.cache?esc(S.cache.name):'通用'} ↗</button></div><div class="split-actions"><button data-action="toggle">${S.running?'Ⅱ 暂停':'▷ 继续'}</button><button class="primary" data-action="stop">结束字幕</button></div>`:`<div class="control-heading"><div class="app-icon"><span class="logo">▥</span></div><div><h2>实时字幕</h2><p>听懂正在播放的内容</p></div></div><div class="control-row"><span>声音来源</span><strong>系统音频</strong></div><div class="control-row"><span>翻译方向</span><strong>英语 → 简体中文</strong></div><div class="control-row"><span>知识库</span><button data-action="knowledge">${S.cache?esc(S.cache.name):'选择领域'} <span>⌄</span></button></div><button class="primary start-button" data-action="start">▷ 开始字幕</button>`}<div class="control-cost">${S.started?'本次预计费用':'OpenAI · Luna'} ${S.started?'<strong>$0.00</strong>':''}</div></div><div class="control-status"><span><i class="dot"></i>${S.started?S.running?'运行中':'已暂停':'准备就绪'}</span><button data-action="settings">设置 ⚙</button></div>`;$('#taskbar-livecap').classList.toggle('active',S.started);$('#tray-state').textContent=S.started?S.running?'Livecap 正在聆听':'Livecap 已暂停':'Livecap 就绪'}
function showControl(){control();$('#control').hidden=false;$('#control').style.zIndex='40';if(!$('#settings').hidden)$('#settings').style.zIndex='45';clampWindow($('#control'))}
function start(){if(!S.started){S.started=true;S.time=0}S.running=true;$('#captions').hidden=false;$('#control').hidden=true;cancelAnimationFrame(frame);lastTime=0;lastPaint=0;frame=requestAnimationFrame(tick);applyCaption();control();syncDock()}
function toggle(){if(!S.started){start();return}S.running=!S.running;cancelAnimationFrame(frame);lastTime=0;if(S.running)frame=requestAnimationFrame(tick);control();paint()}
function stop(){S.started=false;S.running=false;cancelAnimationFrame(frame);$('#captions').hidden=true;syncDock();showControl()}
function partial(){const [zh,en]=lines[Math.floor(S.time/7)%lines.length],r=Math.min(1,(S.time%7+.35)/5.4),units=zh.match(/[A-Za-z][A-Za-z+\/-]*|./gu)||[],words=en.split(' ');return [units.slice(0,Math.max(1,Math.floor(units.length*r))).join(''),words.slice(0,Math.max(1,Math.floor(words.length*r))).join(' ')]}
function setText(el,text){if(el&&el.textContent!==text)el.textContent=text}
function paint(){const [zh,en]=partial();setText($('#caption-zh'),zh);setText($('#caption-en'),en);setText($('#caption-status'),S.running?'正在聆听':'已暂停');$('#caption-pause').textContent=S.running?'Ⅱ':'▷';$('#caption-pause').setAttribute('aria-label',S.running?'暂停字幕':'继续字幕');setText($('#elapsed'),time())}
function tick(now){if(!S.running)return;S.time+=(lastTime?Math.min(now-lastTime,250):0)/1000;lastTime=now;if(now-lastPaint>=80){paint();lastPaint=now}frame=requestAnimationFrame(tick)}
function syncDock(){const c=$('#captions');c.classList.toggle('docked',S.docked);c.classList.toggle('floating',!S.docked);document.documentElement.style.setProperty('--caption-space',S.started&&S.docked?c.offsetHeight+'px':'0px');$('#caption-dock').setAttribute('aria-label',S.docked?'切换为悬浮字幕':'停靠到屏幕底部');if(!S.docked&&!c.hidden)clampWindow(c)}
function changeDock(value){S.docked=value;const c=$('#captions');if(value){c.style.left='';c.style.top='';c.style.width='';c.style.bottom=''}else if(!c.style.top){c.style.width=Math.min(740,innerWidth-24)+'px';c.style.left=Math.max(12,(innerWidth-740)/2)+'px';c.style.top=Math.max(12,innerHeight-48-c.offsetHeight-35)+'px';c.style.bottom='auto'}syncDock()}
function applyCaption(){const c=$('#captions');c.classList.toggle('light',S.theme==='light');c.classList.toggle('zh-only',!S.bilingual);c.classList.toggle('original-first',S.originalFirst);c.style.background=S.theme==='light'?`rgba(248,250,255,${S.opacity/100})`:`rgba(28,32,42,${S.opacity/100})`;$('#caption-zh').style.fontSize=S.size+'px';if(S.started)paint();syncDock()}
function syncSample(){const el=$('#appearance-sample');if(!el)return;el.style.background=S.theme==='light'?`rgba(240,244,251,${S.opacity/100})`:`rgba(28,32,42,${S.opacity/100})`;el.style.color=S.theme==='light'?'#253149':'#e9edf8';el.style.fontSize=S.size+'px'}
function segmented(key,items){return `<div class="segments" role="group" aria-label="${key}">${items.map(([v,label])=>`<button data-setting="${key}" data-value="${v}" class="${String(S[key])===String(v)?'selected':''}" aria-pressed="${String(S[key])===String(v)}">${label}</button>`).join('')}</div>`}
function row(label,value){return `<div class="setting-row"><span>${label}</span>${value}</div>`}
function openSettings(tab=0){S.tab=tab;renderSettings();$('#settings').hidden=false;$('#settings').style.zIndex='45';clampWindow($('#settings'))}
function renderSettings(){const labels=['字幕外观','语言','知识库','连接服务'];$('#settings-nav').innerHTML=labels.map((x,i)=>`<button data-tab="${i}" class="${i===S.tab?'active':''}">${x}</button>`).join('');let html='';if(S.tab===0)html=`<h2>字幕外观</h2>${row('显示方式',segmented('docked',[[true,'底部停靠'],[false,'自由悬浮']]))}${row('主题',segmented('theme',[['dark','深色'],['light','浅色']]))}${row('字号',`<div class="range"><input type="range" min="18" max="32" value="${S.size}" data-range="size" aria-label="字幕字号"><span id="size-value">${S.size}px</span></div>`)}${row('不透明度',`<div class="range"><input type="range" min="50" max="100" value="${S.opacity}" data-range="opacity" aria-label="字幕不透明度"><span id="opacity-value">${S.opacity}%</span></div>`)}<div class="sample-caption" id="appearance-sample" style="font-size:${S.size}px">在 Clang 中，Sema 负责语义分析。<small>In Clang, Sema handles semantic analysis.</small></div>`;
if(S.tab===1)html=`<h2>语言</h2>${row('翻译方向','<span>英语 → 简体中文</span>')}${row('字幕内容',segmented('bilingual',[[true,'双语'],[false,'仅中文']]))}${row('阅读顺序',segmented('originalFirst',[[false,'中文在上'],[true,'英文在上']]))}`;
if(S.tab===2)html=knowledge();if(S.tab===3)html=`<h2>连接服务</h2><div class="connection"><h3>OpenAI <small>已连接</small></h3><p>实时转录 + Luna 翻译</p><button class="small" data-action="check-connection">检查连接</button></div><div class="connection"><h3>Soniox</h3><p>转录、翻译与说话人区分</p><button class="small" disabled>待配置</button></div>`;$('#settings-body').innerHTML=html;updateProgress();syncSample()}
function knowledge(){if(S.building)return `<h2>正在准备知识库</h2><div class="progress-top">${wave()}<div><h3>${esc(S.domain===5?S.custom:S.focus)}</h3><p id="progress-text">${S.progress}%</p></div></div><div class="progress-bar" role="progressbar" aria-label="知识库生成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${S.progress}"><span id="progress-fill"></span></div>${['查找参考资料','整理术语与译法','保存到本地'].map((t,i)=>`<div class="phase" data-phase="${i}"><i>${i+1}</i>${t}</div>`).join('')}<div class="settings-bottom"><button class="quiet small" data-action="cancel-generation">取消</button><button class="small" data-action="pause-generation">${S.generatePaused?'继续':'暂停'}</button></div>`;
if(S.cache&&!S.newKnowledge)return `<div class="cache-head"><h2>知识库</h2><button class="quiet small" data-action="new-knowledge">更换领域</button></div><p class="cache-name">${esc(S.cache.name)}</p><p class="settings-intro"><span class="saved">✓ 已保存到本地</span> · ${S.cache.terms.length} 个术语</p>${S.cache.terms.map((t,i)=>`<div class="term-row"><span>${esc(t.term)}</span><input aria-label="${esc(t.term)} 的译法" value="${esc(t.translation)}" data-term="${i}" maxlength="100"></div>`).join('')}<div class="settings-bottom"><button class="quiet small" data-action="export">导出</button><button class="primary small" data-action="save-terms">保存修改</button></div>`;
return `<h2>选择内容领域</h2><p class="settings-intro">为转录与翻译准备专业词汇。</p><div class="domain-grid" role="group" aria-label="选择领域">${domains.map((d,i)=>`<button data-domain="${i}" class="${S.domain===i?'selected':''}" aria-pressed="${S.domain===i}">${d.name}</button>`).join('')}</div>${S.domain===5?`<input class="custom" id="custom-domain" aria-label="自定义领域" placeholder="例如：芯片设计" value="${esc(S.custom)}">`:`<div class="chips">${domains[S.domain].focus.map(f=>`<button data-focus="${f}" class="${S.focus===f?'selected':''}" aria-pressed="${S.focus===f}">${f}</button>`).join('')}</div>`}<div class="settings-bottom"><span>生成后自动保存</span><button class="primary small" data-action="generate" ${S.domain===5&&!S.custom.trim()?'disabled':''}>生成知识库 →</button></div>`}
function updateProgress(){if(!$('#progress-fill'))return;$('#progress-fill').style.width=S.progress+'%';setText($('#progress-text'),S.generatePaused?'已暂停 · '+S.progress+'%':S.progress+'%');$('.progress-bar').setAttribute('aria-valuenow',S.progress);document.querySelectorAll('[data-phase]').forEach((el,i)=>{const n=Math.min(2,Math.floor(S.progress/34));el.classList.toggle('active',i===n);el.classList.toggle('done',i<n);el.querySelector('i').textContent=i<n?'✓':i+1})}
function generate(){S.building=true;S.generatePaused=false;S.progress=0;renderSettings();clearInterval(generation);generation=setInterval(()=>{if(S.generatePaused)return;S.progress=Math.min(100,S.progress+1);updateProgress();if(S.progress===100){clearInterval(generation);S.building=false;S.newKnowledge=false;const d=domains[S.domain];S.cache={name:S.domain===5?S.custom:S.focus,sample:true,terms:(S.domain===0&&programmingExamples[S.focus]||d.terms).map(t=>({term:t[0],translation:t[1],meaning:t[2]}))};const saved=saveCache();if(S.tab===2)renderSettings();control();if(saved)notice('知识库已就绪')}},80)}
function clampWindow(el){if(el.hidden||el.id==='captions'&&S.docked)return;const r=el.getBoundingClientRect();const x=Math.max(8,Math.min(r.left,innerWidth-r.width-8));const y=Math.max(8,Math.min(r.top,innerHeight-48-Math.min(r.height,innerHeight-64)-8));el.style.left=x+'px';el.style.top=y+'px';el.style.right='auto';el.style.bottom='auto'}
let drag=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag]');if(!handle||e.target.closest('button')||e.button!==0)return;const el=$('#'+handle.dataset.drag),r=el.getBoundingClientRect();drag={el,handle,startX:e.clientX,startY:e.clientY,x:r.left,y:r.top,moved:false,pointer:e.pointerId};handle.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag,dx=e.clientX-d.startX,dy=e.clientY-d.startY;if(!d.moved&&Math.hypot(dx,dy)<5)return;if(!d.moved){d.moved=true;d.el.classList.add('dragging');if(d.el.id==='captions'&&S.docked){changeDock(false);const w=d.el.offsetWidth;d.x=Math.max(8,Math.min(d.startX-w/2,innerWidth-w-8));d.y=Math.min(d.y,innerHeight-d.el.offsetHeight-56)}else d.el.style.zIndex=d.el.id==='settings'?'45':'40'}const w=d.el.offsetWidth,h=d.el.offsetHeight;d.el.style.left=Math.max(8,Math.min(d.x+dx,innerWidth-w-8))+'px';d.el.style.top=Math.max(8,Math.min(d.y+dy,innerHeight-48-h-8))+'px';d.el.style.right='auto';d.el.style.bottom='auto'});
function endDrag(){if(drag){drag.el.classList.remove('dragging');drag=null}}
document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);document.addEventListener('dblclick',e=>{if(e.target.closest('.caption-head')&&!e.target.closest('button'))changeDock(!S.docked)});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.tab!==undefined){S.tab=Number(d.tab);renderSettings();return}if(d.domain!==undefined){S.domain=Number(d.domain);S.focus=domains[S.domain].focus[0]||'';renderSettings();return}if(d.focus){S.focus=d.focus;renderSettings();return}if(d.setting){const value=d.value==='true'?true:d.value==='false'?false:d.value;if(d.setting==='docked')changeDock(value);else S[d.setting]=value;applyCaption();renderSettings();return}switch(d.action){case'start':start();break;case'toggle':toggle();break;case'stop':stop();break;case'show-control':showControl();break;case'minimize':case'hide-control':$('#control').hidden=true;break;case'settings':openSettings(0);break;case'knowledge':openSettings(2);break;case'close-settings':$('#settings').hidden=true;break;case'dock':changeDock(!S.docked);break;case'generate':generate();break;case'new-knowledge':S.newKnowledge=true;renderSettings();break;case'cancel-generation':clearInterval(generation);S.building=false;renderSettings();break;case'pause-generation':S.generatePaused=!S.generatePaused;renderSettings();break;case'save-terms':document.querySelectorAll('[data-term]').forEach(input=>{const v=input.value.trim();if(v)S.cache.terms[Number(input.dataset.term)].translation=v});if(saveCache())notice('已保存');break;case'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(S.cache,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='livecap-knowledge.example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}case'check-connection':b.disabled=true;b.textContent='检查中…';setTimeout(()=>{b.disabled=false;b.textContent='检查连接';notice('连接正常')},700);break}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.range){const k=t.dataset.range;S[k]=Number(t.value);$('#'+k+'-value').textContent=t.value+(k==='size'?'px':'%');syncSample();applyCaption()}if(t.id==='custom-domain'){S.custom=t.value;$('[data-action="generate"]').disabled=!t.value.trim()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#settings').hidden=true;if(e.code==='Space'&&S.started&&!e.target.closest('button,input,textarea')&&$('#settings').hidden){e.preventDefault();toggle()}});
new ResizeObserver(()=>syncDock()).observe($('#captions'));
window.addEventListener('resize',()=>{clampWindow($('#control'));clampWindow($('#settings'));clampWindow($('#captions'));syncDock()});
control();applyCaption();
